import {
  IsNotEmpty,
  IsNumber,
  IsOptional,
  IsString,
  Min,
} from 'class-validator';
import { Type } from 'class-transformer';
import { MaxDecimalPlaces } from '../../utils/validation/max-decimal-places';
import { IsOptionalNotNull } from '../../utils/validation/optional';

export class CreateCustomerDto {
  // Generated by the server; any client value is ignored.
  @IsOptional()
  @IsString()
  code?: string;

  @IsString()
  @IsNotEmpty()
  name: string;

  @IsOptional()
  @IsString()
  taxNumber?: string;

  @IsOptional()
  @IsString()
  commercialRecord?: string;

  @IsOptional()
  @IsString()
  phone?: string;

  @IsOptional()
  @IsString()
  address?: string;

  @IsOptionalNotNull()
  @Type(() => Number)
  @IsNumber()
  @MaxDecimalPlaces(2)
  @Min(0)
  creditLimit?: number;

  // Can be negative: + = the customer owes us, - = we owe the customer.
  @IsOptionalNotNull()
  @Type(() => Number)
  @IsNumber()
  @MaxDecimalPlaces(2)
  openingBalance?: number;
}
